# Hypothesis H: per quadrant, noise color = quad's SECOND-most-frequent color (the "odd" color), 
# and the TRUE reconstruction uses vote only among non-noisy cells, picking the color with max votes;
# ties broken by lowest GLOBAL count. This fit demo4 exactly. Check all demos with various tie-breaks.
def f(g, tieby='gc'):
    H=len(g); W=len(g[0]); hh,qw=H//2,W//2
    Q={'TL':[r[:qw] for r in g[:hh]],'TR':[r[qw:] for r in g[:hh]],'BL':[r[:qw] for r in g[hh:]],'BR':[r[qw:] for r in g[hh:]]}
    gc=collections.Counter(v for q_ in Q.values() for r_ in q_ for v in r_)
    nq={}
    for q_,Vv in Q.items():
        cnt=collections.Counter(v for row_ in Vv for v in row_)
        bg=cnt.most_common(1)[0][0]
        nq[q_]=sorted([c for c,n in cnt.items() if c!=bg])[0] if len(cnt)>1 else None
    res=[]
    for i in range(hh):
        row=[]
        for j in range(qw):
            vals=[Q[q_][i][j] for q_ in ['TL','TR','BL','BR']]
            cnt=collections.Counter()
            for q_,v in zip(['TL','TR','BL','BR'],vals):
                if nq[q_]==v: continue
                cnt[v]+=1
            if not cnt: row.append(vals[0]); continue
            mx=max(cnt.values())
            top=[v for v,n in cnt.items() if n==mx]
            if len(top)==1: row.append(top[0])
            elif tieby=='min': row.append(min(top,key=lambda v:(gc[v],v)))
            elif tieby=='max': row.append(max(top,key=lambda v:(-gc[v],v)))
            else: row.append(min(top,key=lambda v:(gc[v],v)))
        res.append(row)
    return res
